<?php
//POCOR-9835 Starts
namespace Report\Model\Table;

use ArrayObject;
use App\Model\Table\AppTable;
use Cake\Event\EventInterface;
use Cake\Http\ServerRequest;
use Cake\ORM\TableRegistry;
use Cake\Validation\Validator;

/**
 * Reports > Education module page.
 * Lists the education structure features; each feature is generated by a
 * Report.EducationStructure* table.
 */
class EducationTable extends AppTable
{
    public function initialize(array $config): void
    {
        $this->setTable('education_systems');
        parent::initialize($config);

        $this->belongsTo('AcademicPeriods', ['className' => 'AcademicPeriod.AcademicPeriods']);

        $this->addBehavior('Excel', ['pages' => false]);
        $this->addBehavior('Report.ReportList');
    }

    //POCOR-9835: academic_period_id has a default, so the automatic "required" rule is not added - require it here
    public function validationDefault(Validator $validator): Validator
    {
        $validator = parent::validationDefault($validator);
        return $validator
            ->notEmptyString('feature')
            ->notEmptyString('academic_period_id');
    }

    public function beforeAction(EventInterface $event)
    {
        $this->fields = [];
        $this->ControllerAction->field('feature', ['select' => false]);
        $this->ControllerAction->field('academic_period_id', ['type' => 'hidden']);
        $this->ControllerAction->field('format');
    }

    public function onUpdateFieldFeature(EventInterface $event, array $attr, $action, ServerRequest $request)
    {
        $attr['options'] = $this->controller->getFeatureOptions($this->getAlias());
        $attr['onChangeReload'] = true;
        if (!isset($this->request->getData($this->getAlias())['feature'])) {
            $this->request = $this->request->withData($this->getAlias() . '.feature', key($attr['options']));
        }
        return $attr;
    }

    public function onUpdateFieldAcademicPeriodId(EventInterface $event, array $attr, $action, ServerRequest $request)
    {
        $AcademicPeriods = TableRegistry::getTableLocator()->get('AcademicPeriod.AcademicPeriods');
        $attr['type'] = 'select';
        $attr['select'] = false;
        $attr['options'] = $AcademicPeriods->getYearList();
        $attr['default'] = $AcademicPeriods->getCurrent();
        return $attr;
    }

    public function onGetFieldLabel(EventInterface $event, $module, $field, $language, $autoHumanize = true)
    {
        switch ($field) {
            case 'feature':
                return __('Feature');
            case 'format':
                return __('Format');
            case 'academic_period_id':
                return __('Academic Period');
            default:
                return parent::onGetFieldLabel($event, $module, $field, $language, $autoHumanize);
        }
    }
}
//POCOR-9835 Ends
